package Manager;

import java.util.Collection;

import Bean.Accesso;
import DB.DbAccesso;
import DB.DbException;

/** The class AccessManager interacts with the database management classes. The class AccessManager has no dependencies @author Federico Cinque */
public class AccessManager {
	private DbAccesso dbAccesso;
	/** Default constructor of the class AccessManager */
	public AccessManager(){
		dbAccesso=new DbAccesso();
	}
	/** Method that checks the correctness of the login and password of an access by invoking the corresponding method of the db class */
	public boolean controllaAccesso(String login, String password)throws DbException{
		return dbAccesso.controllaAccesso(login, password);
	}
	/** Method that checks the existence of the login by invoking the corresponding method of the db class */
	public boolean controllaLogin(String login)throws DbException{
		return dbAccesso.controllaLogin(login);
	}
	/** Method that returns an access by invoking the corresponding method of the db class */
	public Accesso getAccesso(String login)throws DbException{
		return dbAccesso.getAccesso(login);
	}

	public boolean modificaAccesso(String login, Accesso newAccesso)throws DbException{
		return dbAccesso.modificaAccesso(login, newAccesso);
	}
	/** Method that inserts an access into the db by invoking the corresponding method of the db class */
	public boolean inserisciAccesso(Accesso ac)throws DbException{
		return dbAccesso.inserisciAccesso(ac);
	}
	/** Method that deletes an access from the db by invoking the corresponding method of the db class */
	public boolean eliminaAccesso(String login)throws DbException{
		return dbAccesso.eliminaAccesso(login);
	}
	/** Method that returns all the stored accesses by invoking the corresponding method of the db class */
	public Collection<Accesso> getAccessi()throws DbException{
		return dbAccesso.getAccessi();
	}
}

package Bean;
/** The class Accesso (Access) allows the management of the accesses. The class Accesso has no dependencies @author Federico Cinque */
public class Accesso {

	private String Login;
	private String Password;
	private String Tipo;

	/** Empty constructor of the class Accesso */
	public Accesso(){
		Login=null;
		Password=null;
		Tipo=null;
	}
	/** Constructor of the class Accesso */
	public Accesso(String Login, String Password, String Tipo){
		this.Login=Login;
		this.Password=Password;
		this.Tipo=Tipo;
	}
	/** Method that returns a login */
	public String getLogin() {
		return Login;
	}
	/** Method that sets a login */
	public void setLogin(String login) {
		Login = login;
	}
	/** Method that returns a password */
	public String getPassword() {
		return Password;
	}
	/** Method that sets a password */
	public void setPassword(String password) {
		Password = password;
	}
	/** Method that returns the type of user who accesses */
	public String getTipo() {
		return Tipo;
	}
	/** Method that sets the type of user who accesses */
	public void setTipo(String tipo) {
		Tipo = tipo;
	}
	/** Method that converts the information of an access into a string */
	public String toString() {
		return "Login: "+Login+", Password: "+Password+", Tipo: "+Tipo;
	}
}

package Manager;

import java.util.Collection;

import Bean.Amministratore;
import DB.DbAmministratore;
import DB.DbException;
/** The class AdminManager interacts with the database management classes. The class AdminManager has no dependencies @author Federico Cinque */
public class AdminManager {
	private DbAmministratore dbAmministratore;
	/** Default constructor of the class AdminManager */
	public AdminManager(){
		dbAmministratore = new DbAmministratore();
	}
	/** Method that modifies an administrator by invoking the corresponding method of the db class */
	public boolean modificaAdmin(String matricola, Amministratore newAdmin)throws DbException{
		return dbAmministratore.modificaAmministratore(matricola, newAdmin);
	}
	/** Method that returns an administrator by invoking the corresponding method of the db class */
	public Amministratore ricercaAdminByMatricola(String matricola)throws DbException{
		return dbAmministratore.getAmministratoreByMatricola(matricola);
	}
	/** Method that inserts an administrator into the db by invoking the corresponding method of the db class */
	public boolean inserisciAdmin(Amministratore newAdmin)throws DbException{
		return dbAmministratore.inserisciAmministratore(newAdmin);
	}
	/** Method that deletes an Administrator from the db by invoking the corresponding method of the db class */
	public String eliminaAmministratore(String matricola)throws DbException{
		Collection<Amministratore> Amministratori = dbAmministratore.getAmministratori();
		if(Amministratori.size()>1){
			if(dbAmministratore.eliminaAmministratore(matricola))
				return "ok";
			else
				return "errore";
		}
		else
			return "unico";
	}
	/** Method that returns an administrator by invoking the corresponding method of the db class */
	public Amministratore getAmministratoreByLogin(String login) throws DbException{
		return dbAmministratore.getAmministratoreByLogin(login);
	}
	/** Method that returns a set of administrators by invoking the corresponding method of the db class */
	public Collection<Amministratore> getAmministratoreByName(String nomeAmm,String cognAmm) throws DbException{
		return dbAmministratore.getAmministratoreByName(nomeAmm, cognAmm);
	}
	/** Method that returns all the stored administrators */
	public Collection<Amministratore> getAmministratori() throws DbException{
		return dbAmministratore.getAmministratori();
	}
}

package Bean;
/** The class Amministratore (Administrator) allows the management of the administrators. The class Amministratore has no dependencies @author Federico Cinque */
public class Amministratore {

	private String Nome;
	private String Cognome;
	private String Matricola;
	private String Email;
	private String Login;

	/** Empty constructor of the class Amministratore */
	public Amministratore(){
		Nome=null;
		Cognome=null;
		Matricola=null;
		Email=null;
		Login=null;
	}
	/** Constructor of the class Amministratore */
	public Amministratore(String Nome, String Cognome, String Matricola, String Email, String Login){
		this.Nome=Nome;
		this.Cognome=Cognome;
		this.Matricola=Matricola;
		this.Email=Email;
		this.Login=Login;
	}
	/** Method that returns the first name of the employee */
	public String getNome() {
		return Nome;
	}
	/** Method that sets the first name of the employee */
	public void setNome(String nome) {
		Nome = nome;
	}
	/** Method that returns the last name of the employee */
	public String getCognome() {
		return Cognome;
	}
	/** Method that sets the last name of the employee */
	public void setCognome(String cognome) {
		Cognome = cognome;
	}
	/** Method that returns the employee number (matricola) of the employee */
	public String getMatricola() {
		return Matricola;
	}
	/** Method that sets the employee number (matricola) of the employee */
	public void setMatricola(String matricola) {
		Matricola = matricola;
	}
	/** Method that returns the e-mail of the employee */
	public String getEmail() {
		return Email;
	}
	/** Method that sets the e-mail of the employee */
	public void setEmail(String email) {
		Email = email;
	}
	/** Method that returns the login of the employee */
	public String getLogin() {
		return Login;
	}
	/** Method that sets the login of the employee */
	public void setLogin(String login) {
		Login = login;
	}
	/** Method that converts the information of an access into a string */
	public String toString() {
		return "Nome: "+Nome+", Cognome: "+Cognome+", Matricola: "+Matricola+", e-mail: "+Email+", Login: "+Login;
	}
}

package Bean;

import java.util.Date;
/** It is a JavaBean that manages the methods for setting and returning the attributes of the identity card of a citizen @author Francesco */
public class CartaIdentita {
	/** represents the code of the identity card that is entered by the employee */
	private String Numero;
	private int idCittadino;

	private String Cittadinanza;
	private String Residenza;
	private String Via;
	private String StatoCivile;
	private String Professione;
	private double Statura;
	private String Capelli;
	private String Occhi;
	private String SegniParticolari; 
	private Date DataRilascio;
	private Date DataScadenza;
	private boolean ValidaEspatrio;
	private int num_civico;
	/** Empty default constructor */

	public CartaIdentita() {
		this.num_civico=0;
		this.Capelli=null;
		this.Cittadinanza=null;
		this.DataRilascio=null;
		this.DataScadenza=null;

		this.Numero=null;
		this.Occhi=null;
		this.Professione=null;
		this.Residenza=null;
		this.SegniParticolari=null;
		this.StatoCivile=null;
		this.Statura=0.00;
		this.ValidaEspatrio=false;
		this.Via=null;
	}
	/** object that is returned by the database */
	public CartaIdentita(String cod_carta,int idC,String cittadinanza,String res,String via,int num,
			String stciv,String prof,double stat,String cap,String eyes,String sp,Date dr,Date ds,boolean validEsp){
		this.Numero=cod_carta;
		this.idCittadino=idC;

		this.Cittadinanza=cittadinanza;
		this.Residenza=res;
		this.Via=via;
		this.num_civico=num;
		this.StatoCivile=stciv;
		this.Professione=prof;
		this.Statura=stat;
		this.Capelli=cap;
		this.Occhi=eyes;
		this.SegniParticolari=sp;
		this.DataRilascio=dr;
		this.DataScadenza=ds;
		this.ValidaEspatrio=validEsp;
	}
		// TODO Auto-generated constructor stub
	/** creates the identity card of the citizen who registered in the municipal system, taking from the citizen class the information needed to create the identification document */
	public CartaIdentita(String cod_carta,String surname,String name,Date borndate,String citt,String res,String via,int num,
			String stciv,String prof,double stat,String cap,String eyes,String sp,Date dr,Date ds,boolean validEsp){
		/** the unique code of the identity card requested by the citizen; it is entered by the employee when the paper document is created and when the information has to be kept in the database. */
		this.Numero=cod_carta;
		/** I assign the identity card that I am creating to the citizen who requested it and who is present in the municipal database */

		this.Cittadinanza=citt;
		this.Residenza=res;
		this.Via=via;
		this.num_civico=num;
		this.StatoCivile=stciv;
		this.Professione=prof;
		this.Statura=stat;
		this.Capelli=cap;
		this.Occhi=eyes;
		this.SegniParticolari=sp;
		this.DataRilascio=dr;
		this.DataScadenza=ds;
		this.ValidaEspatrio=validEsp;

	}
	public int id(){
		return idCittadino;
	}
	public void setNumero(String code){
		Numero=code;
	}
	public String getNumero(){
		return Numero;
	}

	public void setCittadinanza(String citta){
		Cittadinanza=citta;
	}
	public String getCittadinanza(){
		return Cittadinanza;
	}
	public String getResidenza(){
		return Residenza;
	}
	public void setResidenza(String res){
		Residenza=res;
	}
	public void setVia(String list){
		Via=list;
	}
	public String getVia(){
		return Via;
	}
	public int getNumCivico(){
		return num_civico;
	}
	public void setNumCivico(int n){
		num_civico=n;
	}
	public void setStatoCivile(String stat){
		StatoCivile=stat;
	}
	public String getStatoCivile(){
		return StatoCivile;
	}
	public void setProfessione(String prof){
		Professione=prof;
	}
	public String getProfessione(){
		return Professione;
	}
	public void setStatura(double stat){
		Statura=stat;
	}
	public double getStatura(){
		return Statura;
	}
	public void setCapelli(String hair){
		Capelli=hair;
	}
	public String getCapelli(){
		return Capelli;
	}
	public void setOcchi(String eyes){
		Occhi=eyes;
	}
	public String getOcchi(){
		return Occhi;
	}
	public String getSegniParticolari(){
		return SegniParticolari;
	}
	public void setSegniParticolari(String listSp){
		SegniParticolari=listSp;
	}
	public void setDataRilascio(Date data){
		DataRilascio=data;
	}
	public Date getDataRilascio(){
		return DataRilascio;
	}
	public void setDataScadenza(Date datas){
		DataScadenza=datas;
	}
	public Date getDataScadenza(){
		return DataScadenza;
	}
	public void setValiditaEspatrio(boolean val){
		ValidaEspatrio=val;
	}
	public boolean isValidaEspatrio(){
		return ValidaEspatrio;
	}

	@SuppressWarnings({ "deprecation", "deprecation", "deprecation" })
	public String toString(){

		int month2=0;
		month2 = getDataRilascio().getMonth();
		int month3=0;
		month3 = getDataScadenza().getMonth();
		return  // I have to retrieve the surname, name and date of birth from the db class

				"Cittadinanza : "+getCittadinanza()+"\n"+
				"Residenza : "+getResidenza()+"\n"+
				"Via : "+getVia()+"\n"+
				"Numero Civico : "+getNumCivico()+"\n"+
				"Stato Civile : "+getStatoCivile()+"\n"+
				"Professione : "+getProfessione()+"\n"+
				"\nCONNOTATI E CONTRASSEGNI SALIENTI\n\n"+
				"Statura : "+getStatura()+"\n"+
				"Capelli : "+getCapelli()+"\n"+
				"Occhi : "+getOcchi()+"\n"+
				"Segni Particolari : "+getSegniParticolari().toString()+"\n"+
				"li : "+getDataRilascio().getDate()+"/"+month2+1+"/"+getDataRilascio().getYear()+"\n"+
				"Data di Scadenza : "+getDataScadenza().getDate()+"/"+month3+1+"/"+getDataScadenza().getYear()+"\n";
	}


}

